describe('File Download on Export Button Click', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should trigger file download when export button is clicked', () => {
    // Verify export button is visible
    cy.get('[data-testid="export-button"]').should('be.visible');
    cy.get('[data-testid="export-button"]').should('contain', 'Download Report');

    // Click export button
    cy.get('[data-testid="export-button"]').click();

    // Verify download dialog appears
    cy.get('[data-testid="download-dialog"]').should('be.visible');

    // Verify download button is present in dialog
    cy.get('[data-testid="download-button"]').should('be.visible');

    // Verify file name is displayed
    cy.get('[data-testid="file-name"]').should('contain', 'Report.pdf');

    // Verify file size is displayed
    cy.get('[data-testid="file-size"]').should('contain', '1.2 MB');

    // Verify download button has correct href
    cy.get('[data-testid="download-button"]').should('have.attr', 'href');
    cy.get('[data-testid="download-button"]').should('have.attr', 'download');

    // Verify file download starts
    cy.intercept('GET', '/api/reports/export/report.pdf').as('downloadReport');
    cy.wait('@downloadReport');

    // Verify download dialog closes after file is downloaded
    cy.get('[data-testid="download-dialog"]').should('not.exist');

    // Verify file is present in downloads folder
    cy.get('[data-testid="downloads-folder"]').should('contain', 'Report.pdf');
  });

  it('should handle failed file download and display error message', () => {
    // Mock API to return error
    cy.intercept('GET', '/api/reports/export/report.pdf', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('failedDownload');

    // Click export button
    cy.get('[data-testid="export-button"]').click();

    // Verify download dialog appears
    cy.get('[data-testid="download-dialog"]').should('be.visible');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to download file');

    // Verify download button is still visible
    cy.get('[data-testid="download-button"]').should('be.visible');

    // Verify file is not downloaded
    cy.get('[data-testid="downloads-folder"]').should('not.contain', 'Report.pdf');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');
  });
});
